from lib import *
L = lambda *a, **k: lesson(37, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Що відбувається зараз", "Сказати, що ви або інші робите просто зараз.",
 "Дія, яка триває саме зараз: am / is / are + дієслово з -ing. I am reading. He is cooking. They are waiting. Скорочено: I'm reading, he's cooking, they're waiting. Підказки часу: now — «зараз», at the moment — «на цей момент».",
 [W("at the moment", "/ət ðə ˈməʊmənt/", "phrase", "зараз, у цей момент", "I'm busy at the moment.", "Я зараз зайнятий."),
  W("stand", "/stænd/", V, "стояти", "He is standing near the door.", "Він стоїть біля дверей."),
  W("look at", "/ˈlʊk ət/", "phrase", "дивитися на", "She is looking at the picture.", "Вона дивиться на картину."),
  W("smile", "/smaɪl/", V, "усміхатися", "She is smiling at me.", "Вона усміхається мені."),
  W("laugh", "/lɑːf/", V, "сміятися", "We are laughing.", "Ми сміємося.")],
 [li("Would you like to come to dinner?", "Повторимо. Ви раді. Що відповісти?", ["I'd love to!", "I love to it!", "I'd like love."], "I'd love to!"),
  mt([("at the moment", "зараз, у цей момент"), ("stand", "стояти"), ("look at", "дивитися на"), ("smile", "усміхатися"), ("laugh", "сміятися")], "Слова для опису того, що відбувається."),
  liu("I'm reading a book at the moment.", "Прослухайте. Що робить людина?", ["Читає книжку", "Купує книжку", "Пише книжку"], "I'm reading."),
  liu("He is standing near the door.", "Прослухайте. Де стоїть чоловік?", ["Біля дверей", "Біля вікна", "Біля столу"], "Near the door."),
  liu("They are listening to music.", "Прослухайте. Що роблять люди?", ["Слухають музику", "Грають музику", "Танцюють"], "Listening to music."),
  fb("She ___ looking at the picture.", ["is", "are", "does"], "She is + дієслово з -ing."),
  fb("I am ___ to music now.", ["listening", "listen", "listens"], "Am + -ing."),
  fb("They ___ waiting at the moment.", ["are", "is", "am"], "They are."),
  mc("Як сказати «Вона дивиться на картину»?", ["She is looking at the picture.", "She looking at picture.", "She is look at the picture."], "She is + looking."),
  bs("Він стоїть біля дверей.", ["He", "is", "standing", "near", "the", "door"], ["stand", "are"], "He is standing near the door."),
  tr("Ми сміємося.", ["We are laughing", "We're laughing"], "We are laughing."),
  li("What is she doing?", "Вона слухає музику. Що відповісти?", ["She is listening to music.", "She listens music now.", "She is listen to music."], "She is listening to music.")])
L(2, "Я зараз не…", "Сказати, що ви чогось зараз НЕ робите.",
 "Заперечення: am / is / are + not + дієслово з -ing. I'm not sleeping. He isn't working. They aren't laughing. Не змінюйте -ing: після not дієслово теж із -ing.",
 [W("cry", "/kraɪ/", V, "плакати", "The baby is crying.", "Дитина плаче."),
  W("talk", "/tɔːk/", V, "розмовляти", "They are talking on the phone.", "Вони розмовляють по телефону."),
  W("shout", "/ʃaʊt/", V, "кричати", "Why are you shouting?", "Чому ти кричиш?"),
  W("whisper", "/ˈwɪspə/", V, "шепотіти", "Why are you whispering?", "Чому ти шепочеш?"),
  W("hurry", "/ˈhʌri/", V, "поспішати", "We aren't hurrying.", "Ми не поспішаємо.")],
 [li("What are you doing at the moment?", "Повторимо. Ви читаєте. Що відповісти?", ["I'm reading.", "I read now.", "I'm read."], "I'm reading."),
  mt([("cry", "плакати"), ("talk", "розмовляти"), ("shout", "кричати"), ("whisper", "шепотіти"), ("hurry", "поспішати")], "Слова для заперечення."),
  liu("The baby is crying.", "Прослухайте. Що робить дитина?", ["Плаче", "Спить", "Сміється"], "Crying — плаче."),
  liu("He isn't working today.", "Прослухайте. Що каже людина?", ["Він сьогодні не працює", "Він працює", "Він хворий"], "Isn't working."),
  liu("We aren't waiting for the bus.", "Прослухайте. Чого вони не роблять?", ["Не чекають автобус", "Не їдуть автобусом", "Не йдуть пішки"], "Aren't waiting."),
  fb("I'm ___ sleeping.", ["not", "no", "don't"], "I'm not + -ing."),
  fb("She ___ working today.", ["isn't", "aren't", "don't"], "She isn't."),
  fb("They aren't ___ on the phone.", ["talking", "talk", "talks"], "Після aren't — дієслово з -ing."),
  mc("Як правильно?", ["He isn't working today.", "He isn't work today.", "He doesn't working today."], "Isn't + -ing."),
  bs("Вона не плаче.", ["She", "isn't", "crying"], ["aren't", "cry"], "She isn't crying."),
  tr("Я зараз не працюю.", ["I'm not working at the moment", "I'm not working now", "I am not working now", "I am not working at the moment"], "I'm not working."),
  li("Are they talking?", "Ні, вони мовчать. Що відповісти?", ["No, they aren't.", "No, they don't.", "No, they not."], "No, they aren't.")])
L(3, "Що ти робиш?", "Запитати, що людина робить зараз, і відповісти.",
 "Питання: Am / Is / Are на початок. Are you listening? Is he working? Коротка відповідь: Yes, I am. No, he isn't. Питання з what: What are you doing? — «Що ти робиш?» Відповідь: I'm cooking dinner.",
 [W("what are you doing", "/ˌwɒt ə ju ˈduːɪŋ/", "phrase", "що ти робиш", "What are you doing?", "Що ти робиш?"),
  W("ask", "/ɑːsk/", V, "питати", "I'm asking a question.", "Я ставлю запитання."),
  W("choose", "/tʃuːz/", V, "вибирати", "She is choosing a dress.", "Вона вибирає сукню."),
  W("have dinner", "/ˌhæv ˈdɪnə/", "phrase", "вечеряти", "We are having dinner.", "Ми вечеряємо."),
  W("practise", "/ˈpræktɪs/", V, "тренуватися", "I'm practising English.", "Я практикую англійську.")],
 [fb("She is ___ to music.", ["listening", "listen", "listens"], "Is + -ing.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("what are you doing", "що ти робиш"), ("ask", "питати"), ("choose", "вибирати"), ("have dinner", "вечеряти"), ("practise", "тренуватися")], "Слова для запитань."),
  liu("What are you doing?", "Прослухайте. Що питає людина?", ["Що ти робиш", "Куди ти йдеш", "Хто ти"], "What are you doing?"),
  liu("I'm calling my mother.", "Прослухайте. Кому телефонує людина?", ["Мамі", "Другові", "Лікареві"], "My mother."),
  liu("We are having dinner.", "Прослухайте. Що роблять люди?", ["Вечеряють", "Готують", "Йдуть у ресторан"], "Having dinner."),
  fb("___ you listening to me?", ["Are", "Do", "Is"], "Are you…?"),
  fb("What ___ you doing?", ["are", "do", "is"], "What are you doing?"),
  fb("Is he working? — No, he ___.", ["isn't", "doesn't", "not"], "No, he isn't."),
  mc("Як відповісти на «What are you doing?» — ви вечеряєте?", ["I'm having dinner.", "I have dinner now.", "I'm have dinner."], "I'm having dinner."),
  bs("Що вона робить?", ["What", "is", "she", "doing"], ["does", "are"], "What is she doing?"),
  tr("Я телефоную мамі.", ["I'm calling my mother", "I am calling my mother"], "I'm calling my mother."),
  li("Are you practising English?", "Так, зараз. Що відповісти?", ["Yes, I am.", "Yes, I do.", "Yes, I practising."], "Yes, I am.")])
L(4, "Правопис з -ing", "Правильно додавати -ing до дієслів.",
 "Здебільшого просто додаємо -ing: read — reading. Дієслово на німе -e: -e відпадає: write — writing, make — making. Короткі дієслова на «приголосна + голосна + приголосна» подвоюють останню літеру: sit — sitting, run — running.",
 [W("writing", "/ˈraɪtɪŋ/", V, "пишу, пише (write без e)", "I'm writing a letter.", "Я пишу листа."),
  W("making", "/ˈmeɪkɪŋ/", V, "готую, готує (make без e)", "She is making tea.", "Вона готує чай."),
  W("sitting", "/ˈsɪtɪŋ/", V, "сиджу, сидить (sit + t)", "He is sitting on the sofa.", "Він сидить на дивані."),
  W("stopping", "/ˈstɒpɪŋ/", V, "зупиняюсь, зупиняється (stop + p)", "The bus is stopping.", "Автобус зупиняється."),
  W("planning", "/ˈplænɪŋ/", V, "планую, планує (plan + n)", "We are planning a trip.", "Ми плануємо подорож.")],
 [li("What is he doing?", "Повторимо. Він телефонує. Що відповісти?", ["He is calling his friend.", "He calls friend now.", "He is call his friend."], "He is calling."),
  mt([("writing", "пишу, пише"), ("making", "готую, готує"), ("sitting", "сиджу, сидить"), ("stopping", "зупиняюсь, зупиняється"), ("planning", "планую, планує")], "Дієслова з особливим -ing."),
  liu("I'm writing a letter.", "Прослухайте. Що робить людина?", ["Пише листа", "Читає листа", "Отримує листа"], "Writing."),
  liu("She is making tea.", "Прослухайте. Що робить жінка?", ["Готує чай", "П'є чай", "Купує чай"], "Making tea."),
  liu("They are running in the park.", "Прослухайте. Де бігають люди?", ["У парку", "На вулиці", "У залі"], "In the park."),
  fb("He is ___ on the sofa.", ["sitting", "siting", "sit"], "sit — sitting (дві t)."),
  fb("I'm ___ a letter.", ["writing", "writeing", "writting"], "write — writing (без e)."),
  fb("She is ___ in the sea.", ["swimming", "swiming", "swims"], "swim — swimming."),
  mc("Яка форма правильна?", ["making", "makeing", "makking"], "make — making."),
  bs("Вони бігають у парку.", ["They", "are", "running", "in", "the", "park"], ["run", "is"], "They are running in the park."),
  tr("Вона готує чай.", ["She is making tea", "She's making tea"], "She is making tea."),
  li("What are they doing?", "Вони плавають. Що відповісти?", ["They are swimming.", "They swiming.", "They are swim."], "They are swimming.")])
L(5, "Зараз чи зазвичай?", "Розрізняти те, що відбувається зараз, і те, що буває завжди.",
 "Звичка або факт: Present Simple — I usually drink tea. Дія саме зараз: Present Continuous — I'm drinking coffee now. Слова-підказки: always, usually, every day → звичка. Now, at the moment, today → зараз.",
 [W("every day", "/ˈevri ˌdeɪ/", "phrase", "щодня", "I walk every day.", "Я ходжу пішки щодня."),
  W("this week", "/ðɪs ˈwiːk/", "phrase", "цього тижня", "This week I'm working at home.", "Цього тижня я працюю вдома."),
  W("these days", "/ˈðiːz deɪz/", "phrase", "ці дні, останнім часом", "These days I'm learning English.", "Останнім часом я вивчаю англійську."),
  W("in the garden", "/ɪn ðə ˈɡɑːdn/", "phrase", "у саду", "She is working in the garden.", "Вона працює в саду."),
  W("at home", "/ət ˈhəʊm/", "phrase", "вдома", "I'm at home now.", "Я зараз удома.")],
 [li("What are you doing now?", "Повторимо. Ви пишете листа. Що відповісти?", ["I'm writing a letter.", "I write a letter now.", "I'm writeing a letter."], "I'm writing."),
  mt([("every day", "щодня"), ("this week", "цього тижня"), ("these days", "останнім часом"), ("in the garden", "у саду"), ("at home", "вдома")], "Слова для порівняння."),
  liu("I walk every day.", "Прослухайте. Як часто людина ходить пішки?", ["Щодня", "Зараз", "Рідко"], "Every day."),
  liu("Today I'm working at home.", "Прослухайте. Де людина працює сьогодні?", ["Вдома", "В офісі", "У кафе"], "At home."),
  liu("I usually drink tea, but today I'm drinking coffee.", "Прослухайте. Що людина п'є сьогодні?", ["Каву", "Чай", "Воду"], "Coffee."),
  fb("I ___ to work every day.", ["walk", "am walking", "walking"], "Every day — звичка: Present Simple."),
  fb("Today I ___ working at home.", ["am", "do", "is"], "Today — зараз: am + -ing."),
  fb("She usually ___ tea, but now she is drinking coffee.", ["drinks", "is drinking", "drink"], "Usually — Present Simple."),
  mc("Яке речення про те, що відбувається зараз?", ["He is sleeping now.", "He sleeps every day.", "He always sleeps."], "Is sleeping + now."),
  bs("Сьогодні я працюю вдома.", ["Today", "I'm", "working", "at", "home"], ["work", "am"], "Today I'm working at home."),
  tr("Я ходжу пішки щодня.", ["I walk every day"], "Every day — Present Simple."),
  li("Do you usually drink coffee?", "Так, але зараз п'єте чай. Що відповісти?", ["Yes, but now I'm drinking tea.", "Yes, but now I drink tea.", "Yes, but now I'm drink tea."], "Yes, but now I'm drinking tea.")])
L(6, "Повторення: що відбувається зараз", "Закріпити Present Continuous.",
 "Нових слів немає. Повторюємо: am / is / are + -ing, заперечення isn't / aren't, питання What are you doing?, правопис writing, sitting, running, а також різницю між «зараз» і «щодня».",
 [],
 [bs("Я зараз читаю.", ["I'm", "reading", "now"], ["read", "is"], "I'm reading now."),
  li("What is he doing?", "Він стоїть біля дверей. Що відповісти?", ["He is standing near the door.", "He stands near door now.", "He is stand near the door."], "He is standing."),
  fb("She ___ crying.", ["isn't", "aren't", "don't"], "She isn't."),
  tr("Що ти робиш?", ["What are you doing"], "What are you doing?"),
  liu("They are talking on the phone at the moment.", "Прослухайте. Що роблять люди?", ["Розмовляють по телефону", "Дивляться телевізор", "Вечеряють"], "Talking on the phone."),
  fb("He is ___ a letter.", ["writing", "writeing", "write"], "write — writing."),
  mc("Як правильно?", ["Are you listening to music?", "Do you listening to music?", "Is you listening music?"], "Are you + -ing?"),
  tr("Я зараз не працюю.", ["I'm not working now", "I am not working now", "I'm not working at the moment", "I am not working at the moment"], "I'm not working."),
  fb("I usually walk to work, but today I ___ driving.", ["am", "do", "is"], "Today — Present Continuous."),
  liu("I'm calling my mother. She is cooking dinner.", "Прослухайте. Що робить мама?", ["Готує вечерю", "Прибирає", "Спить"], "Cooking dinner."),
  bs("Вони не сміються.", ["They", "aren't", "laughing"], ["isn't", "laugh"], "They aren't laughing."),
  li("Are you sleeping?", "Ні, ви читаєте. Що відповісти?", ["No, I'm not. I'm reading.", "No, I don't. I'm reading.", "No, I'm not. I read now."], "No, I'm not.")],
 review=True)
